CREATE TABLE vermietung_briefpapier (id BIGINT PRIMARY KEY CHECK (id=1), version BIGINT NOT NULL, pdf BYTEA NOT NULL, bild BYTEA, gruss TEXT NOT NULL);
CREATE TABLE vermietung_vorlage (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL, mietobjekt_id BIGINT NOT NULL REFERENCES mietobjekt(id), vorgang VARCHAR(30) NOT NULL, inhalt TEXT NOT NULL, UNIQUE(mietobjekt_id,vorgang));
CREATE TABLE vermietung_vorlagenversand (id VARCHAR(36) PRIMARY KEY, buchung_id BIGINT NOT NULL, mietobjekt_id BIGINT NOT NULL, erstellt_am TIMESTAMP WITH TIME ZONE NOT NULL, smtp_am TIMESTAMP WITH TIME ZONE, vorgang VARCHAR(30) NOT NULL, pdf BYTEA NOT NULL, metadaten TEXT NOT NULL, ergebnis VARCHAR(30) NOT NULL, fehler TEXT);
CREATE INDEX ix_vorlagenversand_buchung ON vermietung_vorlagenversand(buchung_id,erstellt_am);
